//! Deserialize and project the Interests API response.

use crate::domain::models::parliament_member::MemberId;
use chrono::Utc;
use serde::Deserialize;
use serde_json::Value;

use super::{ApiError, ParliamentApiClient};
use crate::domain::models::declaration_ingestion::CapturedDeclaration;
use crate::outbound::declaration_source::decode_declaration;

const INTERESTS_URL: &str = "https://interests-api.parliament.uk/api/v2/Interests";

impl ParliamentApiClient {
    pub(super) async fn capture_declarations(
        &self,
        member: MemberId,
    ) -> Result<Vec<CapturedDeclaration>, ApiError> {
        let mut declarations = Vec::new();
        let mut offset = 0;
        loop {
            let url = format!(
                "{INTERESTS_URL}?MemberId={}&Type=Commons&ExcludeExpired=false&ExpandChildInterests=false&Skip={offset}&Take={}",
                member.value(),
                self.batch_size,
            );
            let bytes = self.client.get(url).send().await?.bytes().await?;
            let response: InterestPage = serde_json::from_slice(&bytes)?;
            if response.items.is_empty() {
                break;
            }
            let fetched_at = Utc::now();
            offset += response.items.len();
            for source in response.items {
                declarations.push(decode_declaration(source, fetched_at)?);
            }
            if offset >= response.total_results {
                break;
            }
        }
        Ok(declarations)
    }
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct InterestPage {
    total_results: usize,
    // Retain every source field alongside the typed projection below.
    items: Vec<Value>,
}
//! Minimal client for the UK parliament API

use std::num::NonZeroU8;

use serde::Deserialize;
use thiserror::Error;

use reqwest::Client;

use crate::domain::{
    models::{
        declaration_ingestion::CapturedDeclaration,
        entity_ingestion::EntityIngestionError,
        parliament_member::{MemberId, ParliamentMember},
    },
    repositories::parliament_api::{ParliamentApi as Interface, ParliamentApiError},
};

const BASE_URL: &str = "https://members-api.parliament.uk";

mod declarations;

/// Parliament API implementation
#[derive(Clone)]
pub struct ParliamentApiClient {
    client: Client,
    batch_size: NonZeroU8,
}

impl ParliamentApiClient {
    /// Creates a new instance
    ///
    /// # Errors
    /// - Client error
    pub fn new(batch_size: u8) -> Result<Self, ApiError> {
        let batch_size = NonZeroU8::new(batch_size)
            .ok_or_else(|| ApiError::BuilderError("batch size must be nonzero".into()))?;
        let client = Client::builder()
            .build()
            .map_err(|e| ApiError::BuilderError(e.to_string()))?;

        Ok(Self { client, batch_size })
    }
}

impl Interface for ParliamentApiClient {
    async fn get_sitting_members(&self) -> Result<Vec<ParliamentMember>, ParliamentApiError> {
        let batch = self.batch_size;
        let mut offset = 0;
        let mut members = Vec::new();
        loop {
            let url = format!(
                "{BASE_URL}/api/Members/Search?House=1&IsCurrentMember=true&skip={offset}&take={batch}"
            );
            let result = self
                .client
                .get(url)
                .send()
                .await
                .map_err(|e| ApiError::ResponseError(e.to_string()))?;

            let bytes = result
                .bytes()
                .await
                .map_err(|e| ApiError::ResponseError(e.to_string()))?;

            let response: ParliamentResponse = serde_json::from_slice(&bytes)
                .map_err(|e| ApiError::ResponseError(e.to_string()))?;

            offset += response.items.len();
            members.extend(response.items);

            if members.len() == response.total_results {
                break;
            }
        }

        members
            .into_iter()
            .map(|m| {
                Ok(ParliamentMember::new(
                    m.value.name,
                    MemberId::new(m.value.id)
                        .map_err(|e| ApiError::ResponseError(e.to_string()))?,
                    m.value.party.name,
                    m.value.party.id,
                    m.value.membership.membership_from,
                ))
            })
            .collect()
    }

    async fn get_declarations(
        &self,
        member: MemberId,
    ) -> Result<Vec<CapturedDeclaration>, ParliamentApiError> {
        self.capture_declarations(member).await.map_err(Into::into)
    }
}

#[derive(Clone, Deserialize)]
struct ParliamentResponse {
    items: Vec<NestedMember>,
    #[serde(rename(deserialize = "totalResults"))]
    total_results: usize,
}

#[derive(Clone, Deserialize)]
