    38	impl DeclarationCleaningStorage for ExposedDataPipeline {
    39	    async fn read_captured_declarations(
    40	        &self,
    41	    ) -> Result<Vec<CapturedMemberDeclarations>, EntitySearchPipelineError> {
    42	        if fs::try_exists(self.cleaned_declarations_path())
    43	            .await
    44	            .map_err(read_error)?
    45	        {
    46	            return Err(write_error("cleaned declarations already exist"));
    47	        }
    48	        let directory = self.raw_path().join("declarations");
    49	        let mut files = fs::read_dir(&directory).await.map_err(read_error)?;
    50	        let mut paths = Vec::new();
    51	        while let Some(file) = files.next_entry().await.map_err(read_error)? {
    52	            let path = file.path();
    53	            if path
    54	                .extension()
    55	                .is_some_and(|extension| extension == "parquet")
    56	            {
    57	                paths.push(path);
    58	            }
    59	        }
    60	        paths.sort();
    61	        if paths.is_empty() {
    62	            return Err(read_error("no raw declaration partitions found"));
    63	        }
    64	        paths
    65	            .into_iter()
    66	            .map(|path| {
    67	                read_partition(&path)
    68	                    .map_err(|error| read_error(format!("{}: {error}", path.display())))
    69	            })
    70	            .collect()
    71	    }
