    84	        fs::create_dir_all(parent).await.map_err(write_error)?;
    85	        let staging = parent.join(format!(".declarations-{}", Uuid::now_v7()));
    86	        fs::create_dir(&staging).await.map_err(write_error)?;
    87	        let result = async {
