    38	impl DeclarationCleaningStorage for ExposedDataPipeline {
    39	    async fn read_captured_declarations(
    40	        &self,
    41	    ) -> Result<Vec<CapturedMemberDeclarations>, EntitySearchPipelineError> {
    42	        if fs::try_exists(self.cleaned_declarations_path())
    43	            .await
    44	            .map_err(read_error)?
    45	        {
    46	            return Err(write_error("cleaned declarations already exist"));
    47	        }
    48	        let directory = self.raw_path().join("declarations");
    49	        let mut files = fs::read_dir(&directory).await.map_err(read_error)?;
    50	        let mut paths = Vec::new();
    51	        while let Some(file) = files.next_entry().await.map_err(read_error)? {
    52	            let path = file.path();
    53	            if path
    54	                .extension()
    55	                .is_some_and(|extension| extension == "parquet")
    56	            {
    57	                paths.push(path);
    58	            }
    59	        }
    60	        paths.sort();
    61	        if paths.is_empty() {
    62	            return Err(read_error("no raw declaration partitions found"));
    63	        }
    64	        paths
    65	            .into_iter()
    66	            .map(|path| {
    67	                read_partition(&path)
    68	                    .map_err(|error| read_error(format!("{}: {error}", path.display())))
    69	            })
    70	            .collect()
    71	    }
    72	
    73	    async fn publish_cleaned_declarations(
    74	        &self,
    75	        cleaned: &CleanedDeclarations,
    76	    ) -> Result<(), EntitySearchPipelineError> {
    77	        let destination = self.cleaned_declarations_path();
    78	        if fs::try_exists(&destination).await.map_err(write_error)? {
    79	            return Err(write_error("cleaned declarations already exist"));
    80	        }
    81	        let parent = destination
    82	            .parent()
    83	            .expect("cleaned declarations have a parent");
    84	        fs::create_dir_all(parent).await.map_err(write_error)?;
    85	        let staging = parent.join(format!(".declarations-{}", Uuid::now_v7()));
    86	        fs::create_dir(&staging).await.map_err(write_error)?;
    87	        let result = async {
    88	            write_table(
    89	                &staging.join("funding_entries.parquet"),
    90	                funding_schema(),
    91	                &cleaned.funding_entries,
    92	            )
    93	            .await?;
    25	    fn declarations_path(&self) -> PathBuf {
    26	        self.raw_path().join("declarations")
    27	    }
    28	
    29	    pub(super) async fn write_declaration_partition(
    30	        &self,
    31	        member: MemberId,
    32	        declarations: &[CapturedDeclaration],
    33	    ) -> Result<(), EntitySearchPipelineError> {
    34	        let directory = self.declarations_path();
    35	        fs::create_dir_all(&directory).await.map_err(write_error)?;
    36	        let file = fs::File::create_new(directory.join(member_filename(member)))
    37	            .await
    38	            .map_err(write_error)?;
    39	        let schema = Arc::new(declarations_schema());
    40	        let mut writer =
    41	            AsyncArrowWriter::try_new(file, schema.clone(), None).map_err(write_error)?;
    42	        let records = declarations
    43	            .iter()
    44	            .flat_map(|declaration| {
    45	                if declaration.funding_entries().is_empty() {
    46	                    return vec![DeclarationRecord::new_without_funding_entry(
    47	                        member.value(),
    48	                        declaration.id().value(),
    49	                        declaration.parent_id().map(DeclarationId::value),
    50	                        declaration.category_id(),
    51	                        declaration.category_name().to_string(),
    52	                        declaration.register_id(),
    53	                        declaration.register_published_date(),
    54	                        declaration.registration_date(),
    55	                        declaration.fetched_at(),
    56	                        declaration.source_json().to_string(),
    57	                    )];
    58	                }
    59	
    60	                let mut subrecords = Vec::with_capacity(declaration.funding_entries().len());
    61	                for entry in declaration.funding_entries() {
    62	                    subrecords.push(DeclarationRecord::new_with_funding_entry(
    63	                        member.value(),
    64	                        declaration.id().value(),
    65	                        declaration.parent_id().map(DeclarationId::value),
    66	                        declaration.category_id(),
    67	                        declaration.category_name().to_string(),
    68	                        declaration.register_id(),
    69	                        declaration.register_published_date(),
    70	                        declaration.registration_date(),
    71	                        entry.clone(),
    72	                        declaration.fetched_at(),
    73	                        declaration.source_json().to_string(),
    74	                    ));
    75	                }
    76	                subrecords
    77	            })
    78	            .collect::<Vec<_>>();
    79	
    80	        let mut decoder = ReaderBuilder::new(schema)
    81	            .build_decoder()
    82	            .map_err(write_error)?;
    83	        decoder.serialize(&records).map_err(write_error)?;
    84	        if let Some(batch) = decoder.flush().map_err(write_error)? {
    85	            writer.write(&batch).await.map_err(write_error)?;
    86	        }
    87	        writer.close().await.map_err(write_error)?;
    88	        Ok(())
    89	    }
    90	}
    91	
    92	fn member_filename(member: MemberId) -> String {
    93	    format!("{}.parquet", member.value())
    94	}
    95	
    96	fn write_error(error: impl std::fmt::Display) -> EntitySearchPipelineError {
    97	    EntitySearchPipelineError::WriteError(error.to_string())
    98	}
