   100	pub(super) fn declarations_schema() -> Schema {
   101	    Schema::new(vec![
   102	        Field::new("parliament_member_id", DataType::UInt32, false),
   103	        Field::new("declaration_id", DataType::UInt32, false),
   104	        Field::new("parent_declaration_id", DataType::UInt32, true),
   105	        Field::new("category_id", DataType::UInt32, false),
"}
